_A = 'https://discover.pbc.gov/countycommissioners/Agenda_Master/{}.pdf'
def ag(d, quote):
    return f'BCC agenda {d[:4]}-{d[4:6]}-{d[6:]}: "{quote}" ({_A.format(d)})'

